const cursos = [
  { area: 'frontend', precio: 10, activo: true },
  { area: 'backend', precio: 20, activo: false },
  { area: 'frontend', precio: 30, activo: true },
];

const resultado = cursos
  .filter((curso) => curso.activo)
  .map((curso) => ({
    ...curso,
    precio: curso.precio * 2,
  }))
  .reduce((acc, curso) => {
    const key = curso.area;
    acc[key] = (acc[key] || 0) + curso.precio;
    return acc;
  }, {});

console.log(resultado.frontend);

function resumir(cursos) {
  return cursos
    .filter((curso) => curso.activo)
    .reduce((acc, curso) => {
      const key = curso.area;
      acc[key] = (acc[key] || 0) + curso.precio;
    }, {});
}
